// A sintaxe é JavaScript comum, e é TypeScript válido...
// @ts-expect-error ...mas com noImplicitAny o compilador exige o tipo de "nome"
function saudacaoSemTipos(nome) {
  return "Olá, " + nome.toUpperCase();
}

// A mesma função, agora com os tipos declarados
function saudacao(nome: string): string {
  return "Olá, " + nome.toUpperCase();
}

console.log(saudacao("Ana")); // "Olá, ANA"

// O que escreve em TypeScript:
const idade: number = 30;
const nomes: string[] = ["Ana", "Rui"];

// O que corre depois de compilado (JavaScript puro):
// const idade = 30;
// const nomes = ["Ana", "Rui"];

console.log(idade, nomes.length); // 30 2

const nome: string = "Ana";

// @ts-expect-error o compilador rejeita isto de propósito: é a lição da linha
const errado: number = nome;

console.log(nome); // "Ana"

