function apresentar(nome: string, idade: number): string {
  return `${nome} tem ${idade} anos.`;
}

console.log(apresentar("Rui", 41)); // "Rui tem 41 anos."

function apresentar(nome: string, idade: number): string {
  return `${nome} tem ${idade} anos.`;
}

// @ts-expect-error TS2345: Argument of type 'string' is not assignable to parameter of type 'number'.
console.log(apresentar("Rui", "41"));
